import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Connect a channel","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels.md","filePath":"guide/channels.md"}'),i={name:"guide/channels.md"};function o(r,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="connect-a-channel" tabindex="-1">Connect a channel <a class="header-anchor" href="#connect-a-channel" aria-label="Permalink to &quot;Connect a channel&quot;">​</a></h1><p>An agent can receive conversations from several platforms. Connect the platform first, then approve the people or groups allowed to reach the agent. A valid bot token or linked account does not grant every sender access.</p><table tabindex="0"><thead><tr><th>Guide</th><th>What you need</th><th>Delivery</th><th>Conversations</th></tr></thead><tbody><tr><td><a href="/claude-gateway/channels/telegram.html">Telegram</a></td><td>BotFather bot token</td><td>Long polling</td><td>DMs, groups, supergroups</td></tr><tr><td><a href="/claude-gateway/channels/discord.html">Discord</a></td><td>Bot token, intents and server permissions</td><td>Discord Gateway</td><td>DMs, guild channels and threads</td></tr><tr><td><a href="/claude-gateway/channels/line.html">LINE</a></td><td>Official Account, access token and channel secret</td><td>Signed HTTPS webhook</td><td>DMs, groups and rooms</td></tr><tr><td><a href="/claude-gateway/channels/slack.html">Slack</a></td><td>App bot token and signing secret</td><td>Signed HTTPS Events API</td><td>DMs and channel mentions</td></tr><tr><td><a href="/claude-gateway/channels/whatsapp.html">WhatsApp linked device</a></td><td>Phone account and QR or device pairing code</td><td>Linked device connection</td><td>DMs and groups; multiple accounts</td></tr><tr><td><a href="/claude-gateway/channels/whatsapp-cloud.html">WhatsApp Cloud API</a></td><td>Meta business assets and four credential fields</td><td>Signed HTTPS webhook</td><td>DMs in this integration</td></tr><tr><td><a href="/claude-gateway/channels/wechat.html">WeChat</a></td><td>Personal account eligible for iLink and a QR scan</td><td>iLink long polling</td><td>DMs; one account per agent</td></tr></tbody></table><h2 id="before-you-connect" tabindex="-1">Before you connect <a class="header-anchor" href="#before-you-connect" aria-label="Permalink to &quot;Before you connect&quot;">​</a></h2><p>Create an agent and verify that it can answer in the gateway first. See <a href="/claude-gateway/guide/quickstart.html">getting started</a>. You need permission to configure that agent and permission to create or install the platform app. Platform tokens authenticate the bot to its provider; gateway API keys authenticate administrative requests to the gateway. They are different credentials.</p><p>For Telegram, Discord, LINE and Slack, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span></span></code></pre></div><p>Choose the channel connection step and enter the credentials requested. The same wizard can update or disconnect these four channels. WhatsApp device linking and WeChat use their link controls/API; WhatsApp Cloud credentials are configured in agent settings or the agent configuration.</p><p>The JSON examples in the platform guides are <strong>fragments of an existing <code>agents[]</code> entry</strong> in <code>~/.claude-gateway/config.json</code> (or your <code>GATEWAY_CONFIG</code> file). Keep the entry&#39;s <code>id</code>, <code>workspace</code>, <code>env</code>, <code>claude</code> and other settings. <code>\${VARIABLE}</code> interpolation reads the <strong>gateway process environment</strong>; exporting a variable only inside an agent session does not make it available to the configuration loader. Arrange for your service/container to load those variables, then restart the gateway after manual configuration edits. A missing interpolated variable can cause the affected agent to be skipped at startup.</p><h2 id="approve-access" tabindex="-1">Approve access <a class="header-anchor" href="#approve-access" aria-label="Permalink to &quot;Approve access&quot;">​</a></h2><p>New channel policies are closed by default. <code>dmPolicy</code> and, where supported, <code>groupPolicy</code> use <code>open</code>, <code>allowlist</code> or <code>disabled</code>. <code>pairing</code> is a separate boolean: when enabled under an allowlist policy, a denied sender can receive a code for the administrator to recognize. Turning pairing off keeps the allowlist active and stops new pairing invitations. A disabled policy stays disabled even when pairing is on.</p><p>Telegram and Discord have approval queues:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pending</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_CODE</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deny</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discord</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_CODE</span></span></code></pre></div><p>Only approve requests you recognize. Telegram/Discord store their active policies in the workspace&#39;s channel <code>access.json</code> files. Older files may preserve older behavior, so inspect the effective settings rather than assuming new-agent defaults.</p><p>LINE, Slack, WhatsApp and WeChat instead expose <strong>pending sender discovery</strong>. Compare the code with the sender, then add their stable sender or group ID to the appropriate allowlist in channel settings. The CLI <code>channels approve</code> command does not support these platforms. Removing a pending row only dismisses discovery; it does not approve the sender.</p><h2 id="publish-a-webhook" tabindex="-1">Publish a webhook <a class="header-anchor" href="#publish-a-webhook" aria-label="Permalink to &quot;Publish a webhook&quot;">​</a></h2><p>LINE, Slack and WhatsApp Cloud need a public HTTPS URL that reaches the gateway&#39;s <code>/webhooks/{app}/{agentId}</code> route. For a deployment published under <code>/gateway</code>, a LINE URL is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gateway.example.com/gateway/webhooks/line/assistant</span></span></code></pre></div><p>A direct host without that prefix uses <code>/webhooks/line/assistant</code>. Preserve your deployment&#39;s actual proxy path, and include the agent ID to avoid routing to the first configured agent. <code>gateway.publicUrl</code> describes the public gateway base; setting it does not create DNS, TLS or a tunnel.</p><p>Webhook ingress bypasses gateway API-key authentication because providers authenticate requests with their own signatures. Keep the signed body and signature headers intact, and configure the reverse proxy so these routes do not redirect providers to a login page. All management APIs remain authenticated. See the <a href="/claude-gateway/api/webhooks.html">API reference</a>.</p><h2 id="orchestration-and-voice" tabindex="-1">Orchestration and voice <a class="header-anchor" href="#orchestration-and-voice" aria-label="Permalink to &quot;Orchestration and voice&quot;">​</a></h2><p><code>gateway.orchestration: true</code> enables managed conversations and background tasks across every connected channel. Voice providers and models are configured per agent under <code>agents[].voice</code>. Telegram, Discord, LINE and Slack support voice notes, spoken replies and chat controls; see <a href="/claude-gateway/guide/orchestration.html">orchestration</a> and <a href="/claude-gateway/guide/voice.html">voice setup</a>. WhatsApp and WeChat retain their adapter-specific media limits.</p><h2 id="diagnose-a-silent-bot" tabindex="-1">Diagnose a silent bot <a class="header-anchor" href="#diagnose-a-silent-bot" aria-label="Permalink to &quot;Diagnose a silent bot&quot;">​</a></h2><p>Check these in order:</p><ol><li><strong>Connection:</strong> valid token or linked account; gateway and agent running.</li><li><strong>Delivery:</strong> polling conflict, Discord permissions/intents, or webhook reachability and signature.</li><li><strong>Access:</strong> sender/group allowlist, policy and pairing status.</li><li><strong>Mention:</strong> group mention requirement and the provider&#39;s ability to deliver that message.</li><li><strong>Execution/reply:</strong> agent credentials, provider response errors, media limits and quotas.</li></ol><p>Each guide gives platform-specific checks and a first-message test. For gateway logs and process problems, continue to <a href="/claude-gateway/guide/troubleshooting.html">troubleshooting</a>.</p>`,26)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
